import React from "react";
import { Swiper, SwiperSlide } from "swiper/react";
import "swiper/css";
import "swiper/css/pagination";
import "swiper/css/navigation";
import "swiper/css/effect-coverflow";

import { Pagination, Autoplay, Navigation, EffectCoverflow } from "swiper/modules";

export default function ImageGallery({ nameImages }) {
  const imgGallery = process.env.PUBLIC_URL + "/assets/";

  const formatImageLabel = (imageName) =>
    imageName
      .split("/")
      .pop()
      .replace(/\.(png|jpe?g|webp|avif)$/i, "")
      .replace(/[-_]+/g, " ")
      .replace(/\b\w/g, (char) => char.toUpperCase());

  return (
    <div className="gallery-shell">
      <div className="gallery-glow" />
      <Swiper
        effect={"coverflow"}
        grabCursor={true}
        centeredSlides={true}
        slidesPerView={1.2}
        spaceBetween={24}
        coverflowEffect={{
          rotate: 8,
          stretch: -18,
          depth: 140,
          modifier: 2.2,
          slideShadows: true,
        }}
        pagination={{ clickable: true }}
        loop={true}
        navigation={true}
        autoplay={{
          delay: 3500,
          disableOnInteraction: false,
        }}
        breakpoints={{
          640: {
            slidesPerView: 1.35,
            spaceBetween: 30,
          },
          1024: {
            slidesPerView: 1.7,
            spaceBetween: 36,
          },
        }}
        modules={[EffectCoverflow, Autoplay, Pagination, Navigation]}
        className="gallery-swiper"
      >
        {nameImages.map((item, index) => {
          const label = formatImageLabel(item);

          return (
            <SwiperSlide key={`${item}-${index}`} className="gallery-slide">
              <div className="gallery-frame">
                <img src={imgGallery + item} alt={label} />
                <div className="gallery-overlay">
                  <span className="gallery-badge">Project preview</span>
                  <h4>{label}</h4>
                </div>
              </div>
            </SwiperSlide>
          );
        })}
      </Swiper>
    </div>
  );
}
